import CircularProgress from '@/components/circles/CircularProgress';

interface Props {
    name: string;
    traineeNumberDisplay: string | number;
    roleLabel: string;
    imageSrc: string;
    performancePercent: number;
    performanceBadge: string;
}

export default function TraineeProfileCard({
    name,
    traineeNumberDisplay,
    roleLabel,
    imageSrc,
    performancePercent,
    performanceBadge,
}: Props) {
    return (
        <div className="rounded-2xl bg-[#145DA0] text-[#FFFFFF] shadow-lg overflow-hidden">
            <div className="flex flex-col lg:flex-row lg:items-center gap-6 p-6 md:p-8 lg:gap-10">
                <div className="flex justify-center lg:justify-start shrink-0">
                    <div className="h-36 w-36 sm:h-44 sm:w-44 rounded-full overflow-hidden ring-4 ring-white/25 bg-white/10">
                        <img src={imageSrc} alt="" className="h-full w-full object-cover" />
                    </div>
                </div>
                <div className="flex-1 text-center lg:text-start space-y-2">
                    <h2 className="text-2xl sm:text-3xl font-bold">{name}</h2>
                    <p className="text-white/90 text-base sm:text-lg font-medium">
                        رقم المتدرب: {traineeNumberDisplay}
                    </p>
                    <p className="text-white/85 text-sm sm:text-base">{roleLabel}</p>
                </div>
                <div className="flex flex-col items-center gap-2 shrink-0 lg:min-w-[120px]">
                    <span className="text-sm font-medium text-white/90">معدل الأداء</span>
                    <CircularProgress
                        percentage={performancePercent}
                        size={88}
                        textClassName="text-white font-bold"
                        progressClassName="stroke-white"
                        backgroundClassName="stroke-white/25"
                    />
                    <span className="text-xs font-semibold border border-white/70 px-2 py-1 rounded-md bg-white/10">
                        {performanceBadge}
                    </span>
                </div>
            </div>
        </div>
    );
}
