import { ColumnDef, Row } from '@tanstack/react-table';
import { TraineeEvaluation } from '../../types/configs.types';
import TrashIcon from '@/components/icons/TrashIcon';
import { toast } from 'sonner';
import EditIcon from '@/components/icons/EditIcon';
import { useNavigate } from 'react-router-dom';
import ViewIcon from '@/components/icons/ViewIcon';

// Create a separate component for the actions cell
const ActionsCell = ({ row }: { row: Row<TraineeEvaluation> }) => {
    const handleDelete = (id: number) => {
        toast.error('تم حذف البند بنجاح');
    };
    const navigate = useNavigate();
    return (
        <div className="me-6 text-end flex flex-row items-center justify-end gap-6">
            <button
                onClick={() => navigate(`/human-resources/employee/${row.original.id}/edit`)}
                className="hover:bg-white-blue-300 rounded-full p-1"
            >
                <EditIcon className="text-primery-blue-400" />
            </button>
            <button
                onClick={() => handleDelete(row.original.id)}
                className="hover:bg-white-blue-300 rounded-full p-1"
            >
                <TrashIcon className="text-[#E81E1E] cursor-pointer" />
            </button>
            <button
                onClick={() => navigate(`/trainees/${row.original.id}`)}
                className="hover:bg-white-blue-300 rounded-full p-1"
            >
                <ViewIcon className="text-primery-blue-400" />
            </button>
        </div>
    );
};

export const columns: ColumnDef<TraineeEvaluation>[] = [
    {
        accessorKey: 'review_period',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    الفتره
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="flex flex-row justify-start items-center gap-4 text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                <p className="tracking-normal text-primery-blue-900 font-medium text-sm">{row.original.review_period}</p>

            </div>
        ),
    },
    {
        accessorKey: 'department',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    القسم
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-[#625E74] leading-[26.24px] font-semibold tracking-normal">
                {row.original.department}
            </div>
        ),
    },
    {
        accessorKey: 'attendance_rate',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal text-nowrap">
                    الحضور
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {/* {row.original.current_month_attendance_average} */}
                    {row.original.attendance_rate}
                </div>
            );
        },
    },
    {
        accessorKey: 'review_grade',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal text-nowrap">
                    التقدير
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.review_grade}
                </div>
            );
        },
    },
    {
        accessorKey: 'review_date',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal text-nowrap">
                    تاريخ التقييم
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.review_date}
                </div>
            );
        },
    },


    {
        id: 'actions',
        header: () => {
            return (
                <div className="text-sm text-center px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    الاجراءات
                </div>
            );
        },
        cell: ({ row }) => <ActionsCell row={row} />,
    },
];
