import { Table } from '@tanstack/react-table';
import { Input } from '@/components/ui/input';
import SearchIcon from '@/components/icons/Search';
import { Filters } from '@/types/table.types';
import { TraineeEvaluation } from '../../types/configs.types';

interface TraineeEvaluationsToolbarProps {
    table: Table<TraineeEvaluation>;
    globalFilter: string;
    setGlobalFilter: (value: string) => void;
    filters: Filters;
    setFilters: (value: Filters) => void;
    data: TraineeEvaluation[];
}

export function TraineeEvaluationsToolbar(props: TraineeEvaluationsToolbarProps) {
    const { globalFilter, setGlobalFilter } = props;
    return (
        <div className="flex flex-col p-2 sm:flex-row sm:items-center sm:justify-end">
            <div className="flex flex-row items-center w-full max-w-[287px] border border-white-blue-300 bg-white-blue-50 h-[36px] p-2 rounded-[6px]">
                <Input
                    placeholder="ابحث في التقييمات"
                    value={globalFilter}
                    onChange={(event) => setGlobalFilter(event.target.value)}
                    className="text-white-blue-800 p-0 tracking-normal text-xs lg:text-sm lg:leading-[16.8px] border-none outline-none focus-visible:ring-0 placeholder:text-white-blue-800"
                />
                <button type="button" className="bg-transparent border-none">
                    <SearchIcon className="text-white-blue-800" />
                </button>
            </div>
        </div>
    );
}
