
import { LoadingSpinner } from '@/components/Loading/LoadingSpinner';
import { useParams } from 'react-router-dom';
import { useEffect, useState } from 'react';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { TraineesDetails } from '../types/configs.types';
import TraineeInfo from '../components/trainees-details/TraineeInfo';
import Heading from '../components/trainees-details/Heading';

export default function TraineeDetailsPage() {
    const params = useParams();
    const { id } = params;
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [trainee, setTrainee] = useState<TraineesDetails | null>(null);

    useEffect(() => {
        const fetchTrainee = async () => {
            try {
                const response = await apiGet({ endpoint: endpoints.employee.show + id });
                setTrainee(response.data.data);
            } catch (err) {
                setError('Failed to load trainee details');
            } finally {
                setLoading(false);
            }
        };
        if (id) {
            fetchTrainee();
        } else {
            setError('Invalid trainee ID');
            setLoading(false);
        }
    }, [id]);

    if (loading) {
        return <LoadingSpinner />;
    }
    if (error) {
        return (
            <div className="mt-6 mb-[102px] text-center py-20">
                <h2 className="text-xl text-red-500">{error}</h2>
            </div>
        );
    }
    if (!trainee) {
        return (
            <div className="mt-6 mb-[102px] text-center py-20">
                <h2 className="text-xl">Trainee not found</h2>
            </div>
        );
    }
    return (
        <div className="w-full mt-6 mb-20">
            <Heading />
            <TraineeInfo trainee={trainee} />
        </div>
    );
}